      const x = Number(item.x)
      const y = Number(item.y)
      const width = Number(item.width)
      const height = Number(item.height)
      if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(width) || !Number.isFinite(height)) continue
